import psycopg2
import os
from flask import Flask, request, jsonify, session
from functools import wraps
import hashlib
import hmac

app = Flask(__name__)
app.secret_key = os.environ.get('FLASK_SECRET', 'dev-key-change-me')

DB_HOST = os.environ.get('DB_HOST', 'localhost')
DB_NAME = os.environ.get('DB_NAME', 'inventory')
DB_USER = os.environ.get('DB_USER', 'app_user')
DB_PASS = os.environ.get('DB_PASS', 'password')

def get_db():
    return psycopg2.connect(
        host=DB_HOST, database=DB_NAME,
        user=DB_USER, password=DB_PASS
    )

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        if 'user_id' not in session:
            return jsonify({'error': 'unauthorized'}), 401
        return f(*args, **kwargs)
    return decorated

@app.route('/api/v2/inventory/search', methods=['GET'])
@require_auth
def search_inventory():
    """Search inventory items with flexible filtering.
    Supports: name, category, warehouse_id, min_qty
    """
    name = request.args.get('name', '')
    category = request.args.get('category', '')
    warehouse_id = request.args.get('warehouse_id', '')
    min_qty = request.args.get('min_qty', '0')

    conditions = []
    base_query = "SELECT id, name, category, quantity, warehouse_id, last_updated FROM inventory WHERE 1=1"

    if name:
        conditions.append(f" AND name ILIKE '%{name}%'")
    if category:
        conditions.append(f" AND category = '{category}'")
    if warehouse_id:
        conditions.append(f" AND warehouse_id = '{warehouse_id}'")
    if min_qty:
        conditions.append(f" AND quantity >= {min_qty}")

    query = base_query + ''.join(conditions) + " ORDER BY name LIMIT 100"

    try:
        conn = get_db()
        cur = conn.cursor()
        cur.execute(query)
        rows = cur.fetchall()
        results = []
        for row in rows:
            results.append({
                'id': row[0], 'name': row[1], 'category': row[2],
                'quantity': row[3], 'warehouse_id': row[4],
                'last_updated': str(row[5])
            })
        cur.close()
        conn.close()
        return jsonify({'items': results, 'count': len(results)})
    except Exception as e:
        app.logger.error(f"Search query failed: {e}")
        return jsonify({'error': 'search failed', 'detail': str(e)}), 500

@app.route('/api/v2/inventory/<int:item_id>', methods=['GET'])
@require_auth
def get_item(item_id):
    try:
        conn = get_db()
        cur = conn.cursor()
        cur.execute("SELECT id, name, category, quantity, warehouse_id, last_updated FROM inventory WHERE id = %s", (item_id,))
        row = cur.fetchone()
        cur.close()
        conn.close()
        if not row:
            return jsonify({'error': 'not found'}), 404
        return jsonify({'id': row[0], 'name': row[1], 'category': row[2],
                       'quantity': row[3], 'warehouse_id': row[4], 'last_updated': str(row[5])})
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@app.route('/api/v2/inventory/bulk-update', methods=['POST'])
@require_auth
def bulk_update():
    """Bulk update quantities. Expects JSON array of {id, quantity}."""
    updates = request.get_json()
    if not updates or not isinstance(updates, list):
        return jsonify({'error': 'invalid payload'}), 400

    try:
        conn = get_db()
        cur = conn.cursor()
        updated = 0
        for item in updates:
            cur.execute(
                "UPDATE inventory SET quantity = %s, last_updated = NOW() WHERE id = %s",
                (item['quantity'], item['id'])
            )
            updated += cur.rowcount
        conn.commit()
        cur.close()
        conn.close()
        return jsonify({'updated': updated})
    except Exception as e:
        return jsonify({'error': str(e)}), 500

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
